import{_ as i,o as a,c as e,ag as r}from"./chunks/framework.DXGyWiRo.js";const t="/assets/ch01-c-architecture.DDy4Rg94.png",o="/assets/ch01-02.DNghudKI.png",p="/assets/ch01-03.KtHlKdtp.png",b=JSON.parse('{"title":"走近C语言","description":"","frontmatter":{},"headers":[],"relativePath":"langs/c/01-走近C语言.md","filePath":"langs/c/01-走近C语言.md","lastUpdated":1741365746000}'),h={name:"langs/c/01-走近C语言.md"};function n(s,l,c,d,u,_){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="走近c语言" tabindex="-1">走近C语言 <a class="header-anchor" href="#走近c语言" aria-label="Permalink to &quot;走近C语言&quot;">​</a></h1><h2 id="本章大纲" tabindex="-1">本章大纲 <a class="header-anchor" href="#本章大纲" aria-label="Permalink to &quot;本章大纲&quot;">​</a></h2><ol><li>基本数据类型</li><li>语法结构</li><li>数组</li><li>指针</li><li>结构体</li><li>内存管理</li></ol><h4 id="学习方法" tabindex="-1">学习方法 <a class="header-anchor" href="#学习方法" aria-label="Permalink to &quot;学习方法&quot;">​</a></h4><ul><li>多看</li><li>多敲</li><li>多改</li><li>多实践</li><li>有风格</li></ul><h4 id="计算机系统层次关系" tabindex="-1">计算机系统层次关系 <a class="header-anchor" href="#计算机系统层次关系" aria-label="Permalink to &quot;计算机系统层次关系&quot;">​</a></h4><p><img src="'+t+'" alt="img"></p><ol><li>CodeBlocks</li><li>VC++</li><li>VS2010</li><li>VS Code</li><li>GCC、G++</li></ol><h4 id="软件、语言与程序" tabindex="-1">软件、语言与程序 <a class="header-anchor" href="#软件、语言与程序" aria-label="Permalink to &quot;软件、语言与程序&quot;">​</a></h4><p>计算机软件：由计算机程序及其数据文件组成。</p><p>计算机语言：人与计算机交流的工具，一套语法规则，语句（语法、语义）</p><p>计算机程序：完成特定功能的语句序列</p><p>程序设计：用计算机语言编写程序的过程</p><p>算法（Algorithm）：能够解决一类问题的过程和方法</p><h4 id="程序语言" tabindex="-1">程序语言 <a class="header-anchor" href="#程序语言" aria-label="Permalink to &quot;程序语言&quot;">​</a></h4><ul><li>机器语言（０１）</li><li>低级语言（汇编）</li><li>高级语言（C语言）</li></ul><p>机器语言：由计算机硬件系统可以识别的<strong>二进制指令</strong>组成的语言</p><p>低级语言：接近机器语言的表示方法，使用人类比较容易记忆的单字形式来对应一连串的0、1组合。</p><p>汇编语言：将机器指令映射为一些可以被人读懂的**助记符，**如ADD，SUB。</p><p>汇编：汇编语言程序 --&gt; 机器语言程序</p><p>高级语言：用类似于人类自然语言和数字语言的方式描述问题、编写程序。编译、链接。</p><p><img src="'+o+`" alt="img"></p><p>1980年 贝尔实验室的 Bjarne Stroustrup博士及其同事对 C 语言进行了改进和扩充，并引入了类的概念。</p><p>1983年，由 Rick Mascitti 提议正式命名为C++（C Plus Plus）</p><h4 id="c与c" tabindex="-1">C与C++ <a class="header-anchor" href="#c与c" aria-label="Permalink to &quot;C与C++&quot;">​</a></h4><ul><li>贝尔实验室于二十世纪八十年代在C语言的基础上开发的。</li><li>C++是C语言的超集，包含了C语言的所有内容，同时增加了面向对象编程方面的内容。</li></ul><h4 id="c与java" tabindex="-1">C与Java <a class="header-anchor" href="#c与java" aria-label="Permalink to &quot;C与Java&quot;">​</a></h4><ul><li>Sun公司于1995年发布的面向对象编程语言</li><li>Java也是基于C语言的</li></ul><h4 id="c与c-sharp" tabindex="-1">C与C Sharp <a class="header-anchor" href="#c与c-sharp" aria-label="Permalink to &quot;C与C Sharp&quot;">​</a></h4><ul><li>微软在2000年6月与.NET平台一同推出</li><li>C#也是从C语言派生的一种面向对象语言</li></ul><h4 id="程序开发过程基本术语" tabindex="-1">程序开发过程基本术语 <a class="header-anchor" href="#程序开发过程基本术语" aria-label="Permalink to &quot;程序开发过程基本术语&quot;">​</a></h4><ul><li>源程序：用源语言写的，有待翻译的程序</li><li>目标程序：源程序通过翻译程序加工以后所生成的程序</li><li>编译程序：把源程序翻译成等价的目标程序的程序</li></ul><h4 id="c语言程序的开发过程" tabindex="-1">C语言程序的开发过程 <a class="header-anchor" href="#c语言程序的开发过程" aria-label="Permalink to &quot;C语言程序的开发过程&quot;">​</a></h4><ol><li>定义程序目标</li><li>设计程序</li><li>编写代码</li><li>编译</li><li><ul><li>编译器：源代码.c--&gt;目标代码.obj</li><li>链接器:（目标代码＋库函数文件）--&gt;.exe</li></ul></li><li>运行</li><li>测试</li><li>调试程序</li></ol><h4 id="_1、定义程序目标" tabindex="-1">1、定义程序目标 <a class="header-anchor" href="#_1、定义程序目标" aria-label="Permalink to &quot;1、定义程序目标&quot;">​</a></h4><p>在开始解决问题之前，程序的开发人员必须彻底了解问题的是什么，对即将要创建的程序要做的事情有个清晰的想法。这需要仔细考虑以下问题:</p><ul><li>程序需要什么信息</li><li>程序需要执行哪些计算和操作</li><li><pre><code>程序应该报告什么信息。 例如，计算任意一个圆环的面积
</code></pre></li><li><pre><code>提出问题，明确目标
</code></pre></li><li><pre><code>圆环是什么？如何计算？计算精度？
</code></pre></li></ul><h4 id="_2、设计程序" tabindex="-1">2、设计程序 <a class="header-anchor" href="#_2、设计程序" aria-label="Permalink to &quot;2、设计程序&quot;">​</a></h4><p>决定程序如何去解决问题。 需要考虑：</p><ul><li>如何给程序提供必要的数据</li><li>程序中如何表示数据</li><li>用什么方法来处理数据</li><li>程序如何组织</li><li>程序怎样报告结果</li><li>完成这个程序需要多长时间</li></ul><p>应该用一般的概念考虑设计中的问题，而不是考虑具体的代码。</p><h4 id="_3、编写代码" tabindex="-1">3、编写代码 <a class="header-anchor" href="#_3、编写代码" aria-label="Permalink to &quot;3、编写代码&quot;">​</a></h4><ul><li>编写代码来实现前面的设计，即用某一门语言来表示程序设计。</li><li>需要开发人员熟练掌握该语言的知识。</li><li>可以在草稿纸上勾画自己的想法或书写代码，但最终必须将代码输入计算机。</li><li>输入代码所采用的机制则取决于具体的编程环境。</li><li>一般来说，需要使用文本编辑器（例如Windows的记事本程序）来创建一种文件，称为源文件</li><li>源文件包含程序设计的C语言表示形式（称为源程序或源代码）</li></ul><h4 id="_4、编译" tabindex="-1">4、编译 <a class="header-anchor" href="#_4、编译" aria-label="Permalink to &quot;4、编译&quot;">​</a></h4><p>把C语言源程序转换成机器语言表示的程序。</p><ul><li>这种程序可以直接被计算机理解和执行，所以称之为<strong>可执行程序</strong>，放在可执行文件中。</li><li>编译的具体细节取决于使用的编程环境。</li></ul><p>C语言分两步完成这一工作：<strong>编译</strong>和<strong>链接</strong>。</p><ul><li><p>编译器将源代码转换为<strong>目标代码</strong>，并存在目标文件中。</p></li><li><p>链接器将目标代码与其他代码结合起来生成可执行文件。</p></li><li><p>这种把编译和链接分开来做的方法便于程序的模块化。</p></li><li><p>可以分别编译程序的各个模块，然后用链接器把编译过的模块结合起来。</p></li><li><p>这样，如果需要改变一个模块，则不需要重新编译所有其他模块。</p></li></ul><h4 id="_5、6、7、运行、测试和调试程序" tabindex="-1">5、6、7、运行、测试和调试程序 <a class="header-anchor" href="#_5、6、7、运行、测试和调试程序" aria-label="Permalink to &quot;5、6、7、运行、测试和调试程序&quot;">​</a></h4><p>运行包含可执行程序的文件，观察运行的结果。</p><ul><li><p>在不同的系统中运行程序的方式可能不同。</p></li><li><p>例如，Windows的控制台和资源管理器。</p><p>应该对程序进行仔细的检查，看程序是否在做该做的事。</p></li><li><p>比较好的做法是为验证程序的正确性设计一个测试计划。</p></li><li><p>越早做越好，因为它有助于理清程序员的思路。</p></li></ul><p>程序中的错误被称为bug，调试（Debug）就是要发现并修正错误。</p><p><img src="`+p+'" alt="img"></p>',53)])])}const m=i(h,[["render",n]]);export{b as __pageData,m as default};
